import {regionMaps as outdoorMaps,mapSource} from '../region-maps.js';
import {storyMaps} from '../story-maps.js';
import {storyWaypoints} from '../story-data.js';
export const regionMaps={...outdoorMaps,...storyMaps};
import {puzzles} from '../puzzle-data.js';
import {collectionItems,artifactCandidates} from '../collection-data.js';
import {artifactForCandidate,artifactDone} from './artifacts.js';
export {mapSource};
export const mapNodeMatches=(node,target)=>node.target===target||node.alsoTargets?.includes(target);
export function mapNodeDone(node,progress){const site=node.target?.startsWith('artifact-')?artifactForCandidate(node.target.slice(9)):null;return site?artifactDone(progress,site.id):[node.target,...node.alsoTargets||[]].every(target=>target&&progress.steps[target]?.status==='completed');}
export function mapNodeTitle(node){const puzzle=puzzles.find(p=>'puzzle-'+p.id===node.target),item=collectionItems.find(c=>'collectible-'+c.id===node.target),artifact=artifactCandidates.find(a=>'artifact-'+a.id===node.target),waypoint=storyWaypoints.find(w=>'waypoint-'+w.id===node.target);if(node.kind==='star-point')return puzzle.title+' · '+node.title;return puzzle?puzzle.label+' · '+puzzle.title:item?item.title:artifact?artifact.title:waypoint?waypoint.title:node.caption||node.description||node.label;}
export function activeStarRoute(map,selected){const node=map?.nodes.find(n=>n.id===selected);return node?.routeId||(node?.kind==='star'?node.target.slice(7):'');}
const visibleNodes=(map,selected)=>{const route=activeStarRoute(map,selected);return map.nodes.filter(n=>n.kind==='star-point'?n.routeId===route:!route||['puzzle','lost','gold','landmark'].includes(n.kind)||(n.kind==='star'&&n.target==='puzzle-'+route));};
const selectionText=node=>mapNodeTitle(node)+(node.description?' · '+node.description:'');
export function mapSvg(region,{escape,progress,selected}){
 const map=regionMaps[region];if(!map)return '';const nodes=visibleNodes(map,selected),route=nodes.filter(n=>n.kind==='star-point');
 const xs=nodes.flatMap(n=>[n.x,n.anchorX??n.x]),ys=nodes.flatMap(n=>[n.y,n.anchorY??n.y]),bounds=route.length?[Math.max(0,Math.min(...xs)-55),Math.max(0,Math.min(...ys)-55),Math.min(1000,Math.max(...xs)+75),Math.min(650,Math.max(...ys)+55)]:[0,0,1000,650],viewBox=[bounds[0],bounds[1],bounds[2]-bounds[0],bounds[3]-bounds[1]].join(' ');
 const [nx,ny]=map.north||[0,0],end=[nx*45,ny*45],back=[nx*29,ny*29],wing=[-ny*9,nx*9];
 const compass=map.north?`<g class="map-compass" transform="translate(${route.length?bounds[2]-75:920} ${route.length?bounds[1]+80:85})" aria-label="大致北向"><path d="M0 0L${end.join(' ')}M${back[0]+wing[0]} ${back[1]+wing[1]}L${end.join(' ')}L${back[0]-wing[0]} ${back[1]-wing[1]}"/><text x="${nx*67}" y="${ny*67+10}" text-anchor="middle">N</text></g>`:'';
 return `<svg class="region-map-svg" viewBox="${viewBox}" role="group" aria-label="${escape(map.name||region)} 位置示意圖" xmlns="http://www.w3.org/2000/svg"><title>${escape(map.name||region)} 位置示意圖</title>${compass}<g class="map-paths" fill="none">${map.paths.map(path=>'<polyline points="'+path.map(xy=>xy.join(',')).join(' ')+'"/>').join('')}</g>${route.length?'<g class="map-star-order" fill="none">'+route.slice(1).map((n,i)=>n.routeIndex===route[i].routeIndex+1?`<polyline points="${route[i].anchorX},${route[i].anchorY} ${n.anchorX},${n.anchorY}"/>`:'').join('')+'</g><g class="map-star-leaders">'+route.map(n=>`<path d="M${n.anchorX} ${n.anchorY}L${n.x} ${n.y}"/><circle cx="${n.anchorX}" cy="${n.anchorY}" r="10"/>`).join('')+'</g>':''}${nodes.map(node=>`<a href="#${escape(node.target||'map-'+node.id)}" data-map-node="${escape(node.id)}" ${node.target?'data-map-target="'+escape(node.target)+'"':''} class="map-node map-${node.kind}${mapNodeDone(node,progress)?' map-done':''}${selected===node.id?' map-selected':''}" aria-label="${escape(node.label+' · '+mapNodeTitle(node)+(mapNodeDone(node,progress)?' · 已取得':''))}"><title>${escape(selectionText(node)+(mapNodeDone(node,progress)?' · 已取得':''))}</title><circle cx="${node.x}" cy="${node.y}" r="25"/><text x="${node.x}" y="${node.y+1}" text-anchor="middle" dominant-baseline="central">${escape(node.label)}</text>${node.caption?`<text class="map-caption" x="${node.x}" y="${node.y+(node.captionDy||52)}" text-anchor="middle">${escape(node.caption)}</text>`:''}${mapNodeDone(node,progress)?`<path class="map-completed-mark" d="M${node.x+13} ${node.y-24}l6 6 12-14"/>`:''}</a>`).join('')}</svg>`;
}
export function regionMapHtml(region,options,{dialog=false}={}){
 const map=regionMaps[region];if(!map)return '';
 const node=map.nodes.find(n=>n.id===options.selected),route=activeStarRoute(map,options.selected),stars=map.nodes.filter(n=>n.kind==='star'),puzzle=puzzles.find(p=>p.id===route),escape=options.escape;
 return `<section class="region-map-panel" data-map-region="${region}" aria-label="${region} 區域地圖"><div class="map-heading"><h2>${escape(map.name||region+' 區域示意圖')}</h2>${dialog?'<label class="map-fit-label"><input type="checkbox" data-map-fit checked>全圖</label>':'<button type="button" data-open-map>放大地圖</button>'}</div>${options.mapKeys?.length>1?`<label class="map-layer-label">範圍<select data-map-layer>${options.mapKeys.map(key=>`<option value="${escape(key)}" ${region===key?'selected':''}>${escape(regionMaps[key].name||key)}</option>`).join('')}</select></label>`:''}${stars.length?'<div class="map-star-routes" aria-label="星星路線">'+stars.map(n=>`<button type="button" data-map-star="${n.id}" aria-pressed="${n.target==='puzzle-'+route}">${escape(puzzles.find(p=>'puzzle-'+p.id===n.target).title)}</button>`).join('')+(route?'<button type="button" data-map-star-clear>區域總覽</button>':'')+'</div>':''}${route?'<p class="map-star-context"><strong>'+escape(puzzle.title)+'・P 點對應下方攻略</strong><br>編號是搜尋區／觀察站位；細線連到地標，藍虛線只表操作順序。</p>':''}<div class="map-canvas map-fit">${mapSvg(region,options)}</div><p class="map-selection" data-map-selection>${node?escape(selectionText(node)):(stars.length?'閱讀星星段落時會自動標出路線；也可點圖或選擇位置。':'點圖上標記，或在下方選擇位置。')}</p><label class="map-select-label">定位<select data-map-select><option value="">選擇謎題或收集品…</option>${map.nodes.map(n=>'<option value="'+escape(n.id)+'" '+(n.id===options.selected?'selected':'')+'>'+escape(n.label+' · '+mapNodeTitle(n))+'</option>').join('')}</select></label><p class="map-legend">${map.legend?escape(map.legend).replaceAll('\n','<br>'):'1–8 正規 · L1／L2 遺失 · G 黃金<br>實 實驗室 · T／L 錄音 · M 光影<br>★ 領星雕像 · P 星星導引 · A 遺物候選<br>火：橘紅跳題 Spark，並非追逐用藍光<br>綠色＋勾號：已取得（遺物跨區連動）'}</p><p class="map-orientation">${escape(map.orientation)}</p>${map.pending?'<p class="map-pending">待查證：'+escape(map.pending)+'</p>':''}${dialog?'<p class="map-note">'+escape(map.note)+'</p><a href="'+(map.sourceUrl||mapSource.url)+'" target="_blank" rel="noopener noreferrer">地標查證來源 ↗</a>':''}</section>`; // taste-skill-ignore: ★ 是本遊戲星星收集的既有識別，非裝飾 emoji。
}
export const mapLocateButton=(target,escape)=>`<button type="button" class="map-locate" data-map-locate="${escape(target)}" aria-label="在區域地圖定位">定位</button>`;
